                dst.head.value = (int64_t) ( ( base + at ) - (const uint8_t *) &dst.head );
                if ( !ListNodePack( ctx, seen, *pointee, *child, base, capacity, used ) ) { return false; }
                TablePackMapClose( seen, (const void *) pointee, slot );
